      "title": "Betrayal at the Altar",
      "start_block": "B004",
      "end_block": "B012",
      "hook": "Gerald steps forward with a smug grin, mocking Juliana as a 'discarded bride' while Clarissa laughs cruelly.",
      "cliffhanger": "Clarissa taunts that Juliana has found a man just as worthless as she is thought to be.",
      "why": "Immediate public humiliation and betrayal hook the viewer with high emotional stakes and clear villains.",
      "context_gap": "None; the insult implies a wedding context where Juliana was abandoned."
    },
    {
      "title": "The Stranger's Vow",
      "start_block": "B023",
      "end_block": "B046",
      "hook": "Juliana asks why the stranger would offer his name after hearing the insults, looking vulnerable.",
      "cliffhanger": "The Mysterious Bearded Man declares it is not pity, but a vow, leaving Juliana stunned.",
      "why": "A powerful romantic declaration amidst public shame creates intense tension and curiosity about the stranger's identity.",
      "context_gap": "Strangers might not know he is a Duke or why he knows her pain so deeply without prior context."
    },
    {
      "title": "Disowned and Walking Away",
      "start_block": "B096",
      "end_block": "B108",
      "hook": "Lady Ashcroft screams that Juliana is disowned and forbids bringing the stranger near their manor.",
      "cliffhanger": "Juliana and the warrior turn their backs on the screaming family and walk toward the open doors into the light.",
      "why": "The ultimate rejection followed by a defiant exit creates a satisfying yet unresolved feeling of a new beginning.",
      "context_gap": "Viewers need to know the couple is now exiled and facing an unknown future together."
    }
  ],
  "moments": [
    {
      "start_block": "B005",
      "end_block": "B007",
      "kind": "hook",
      "description": "Gerald mocks Juliana as a discarded bride for a penniless nobody."
    },
    {
      "start_block": "B024",
