      "description": "The stranger insists his proposal is a vow, not pity."
    },
    {
      "start_block": "B099",
      "end_block": "B099",
      "kind": "cliffhanger",
      "description": "Lady Ashcroft shouts that Juliana is officially disowned."
    }
  ]
}
